  ((SELECT id FROM sls WHERE kode_sls = '5205040002000700'), 'ca8f12d4-b0e9-4d56-8abc-f3f5f1aa0493#1', 'Kios Fitri <Fitri Yulianti>', NULL, 'UMKM', 'G', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SUBMITTED BY Pencacah', '2026-07-29 09:42:53', '2026-08-10 17:09:52'),
  ((SELECT id FROM sls WHERE kode_sls = '5205040002000700'), 'd4f20837-fe3f-4db3-8c7d-57b71a82a26a#1', 'UTP TANAMAN JAGUNG (MAHDIN) ', 'MAHDIN', 'keluarga', 'A', '[A] 01111 Pertanian Jagung', 75000000.0, NULL, 46650000.0, NULL, 22450000.0, NULL, 15700000.0, NULL, 3500000.0, NULL, 5000000.0, NULL, 19, 'Melakukan budidaya tanaman jagung yang meliputi pengolahan lahan, penanaman, pemeliharaan tanaman (pemupukan, penyiraman, dan pengendalian hama/penyakit), pemanenan, serta penanganan pascapanen seperti pengeringan, pemipilan, penyortiran, dan penyimpanan.', 'SUBMITTED BY Pencacah', '2026-07-11 18:01:05', '2026-08-10 17:09:52'),
